sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading) {
        return;
    }

    var regex = /^[0-9]+$/; //Regex: ensures the field contains only numbers
    var outcome = g_form.getValue('u_outcome');
    var mar_1 = g_form.getValue('u_martini_reference_1');
    var mar_2 = g_form.getValue('u_martini_reference_2');

    if (mar_2 == '') {
        g_form.clearValue('comments');
        if (mar_1 != '') {
            if (g_scratchpad.collateral_task_type == 'Base Task') {

                if (outcome == "Action required in Martini - Cancel & Amend" || outcome == "Action required in Martini - Book/Amend/Cancel") {
                    g_form.setValue('comments', "Please commit - \n\n" + mar_1);
                } else {
                    g_form.setValue('comments', "Please unsettle - \n\n" + mar_1);
                }
            } else {
                g_form.setValue('comments', "Please commit - \n\n" + mar_1);
            }
        }
    } else {
        if (!regex.test(mar_2)) {
            g_modal.alert('Martini Reference fields can accept only numeric values (0-9)');
            setTimeout(function() {
                g_form.clearValue('u_martini_reference_2');
            }, 5);
        } else if (mar_1 != '' && (mar_1 == mar_2)) {
            g_modal.alert("Martini Reference fields cannot have the duplicate values");
            setTimeout(function() {
                g_form.clearValue('u_martini_reference_1');
                g_form.clearValue('u_martini_reference_2');
            }, 5);
        } else {
            var temp_mar1 = (mar_1) ? mar_1 + "\n\n" : '';
            if (g_scratchpad.collateral_task_type == 'Base Task') {

                if (outcome == "Action required in Martini - Cancel & Amend" || outcome == "Action required in Martini - Book/Amend/Cancel") {
                    g_form.setValue('comments', "Please commit - \n\n" + temp_mar1 + mar_2);
                } else {
                    g_form.setValue('comments', "Please unsettle - \n\n" + temp_mar1 + mar_2);
                }
            } else {
                g_form.setValue('comments', "Please commit - \n\n" + temp_mar1 + mar_2);
            }
        }
    }
}
